-- Staging schema fixture for the web write paths, captured from PostgreSQL 18.3 catalogs.
-- Contains table definitions only. This is not a production migration.
BEGIN;
CREATE SEQUENCE public."post_extraction_logs_id_seq";
CREATE SEQUENCE public."post_images_id_seq";
CREATE SEQUENCE public."post_moderation_events_id_seq";
CREATE SEQUENCE public."stage1_claims_id_seq";

CREATE TABLE public."ai_prompt_versions" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "version" integer NOT NULL,
    "system_prompt" text NOT NULL,
    "description" text,
    "is_active" boolean DEFAULT false NOT NULL,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."api_credentials" (
    "service" character varying(30) NOT NULL,
    "encrypted_token" text NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."author_skip_list" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "facebook_author_id" character varying(255),
    "profile_url" text,
    "display_name" character varying(255),
    "classification" character varying(30) DEFAULT 'unknown'::character varying NOT NULL,
    "skip_enabled" boolean DEFAULT false NOT NULL,
    "reason" text,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."crawl_runs" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "apify_run_id" character varying(255) NOT NULL,
    "apify_dataset_id" character varying(255),
    "scan_id" uuid,
    "source" character varying(30),
    "status" character varying(30) NOT NULL,
    "total_posts" integer DEFAULT 0 NOT NULL,
    "inserted_posts" integer DEFAULT 0 NOT NULL,
    "duplicate_posts" integer DEFAULT 0 NOT NULL,
    "skipped_posts" integer DEFAULT 0 NOT NULL,
    "error_message" text,
    "started_at" timestamp with time zone DEFAULT now() NOT NULL,
    "finished_at" timestamp with time zone
);

CREATE TABLE public."crawler_settings" (
    "id" integer DEFAULT 1 NOT NULL,
    "max_posts_per_group" integer DEFAULT 3 NOT NULL,
    "only_new_posts" boolean DEFAULT true NOT NULL,
    "max_total_charge_usd" numeric(8,2) DEFAULT 0.30 NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."collector_scan" (
    "id" smallint NOT NULL,
    "revision" bigint DEFAULT 0 NOT NULL,
    "scan_id" uuid,
    "source" text,
    "state" text DEFAULT 'IDLE'::text NOT NULL,
    "apify_run_id" character varying(255),
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "collector_scan_id_check" CHECK ((id = 1)),
    CONSTRAINT "collector_scan_pkey" PRIMARY KEY (id),
    CONSTRAINT "collector_scan_source_check" CHECK ((source = ANY (ARRAY['manual'::text, 'scheduler'::text]))),
    CONSTRAINT "collector_scan_state_check" CHECK ((state = ANY (ARRAY['IDLE'::text, 'QUEUED'::text, 'STARTING'::text, 'RUNNING'::text, 'FAILED'::text, 'UNKNOWN'::text])))
);

CREATE TABLE public."facebook_groups" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "name" character varying(255) NOT NULL,
    "url" text NOT NULL,
    "enabled" boolean DEFAULT true NOT NULL,
    "max_posts" integer,
    "facebook_group_external_id" character varying(255),
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."post_classifications" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "post_id" bigint NOT NULL,
    "prompt_version_id" bigint NOT NULL,
    "model" character varying(100) NOT NULL,
    "post_type" character varying(30) NOT NULL,
    "seller_type" character varying(30) NOT NULL,
    "confidence" double precision,
    "products" jsonb DEFAULT '[]'::jsonb NOT NULL,
    "location" text,
    "reason" text,
    "raw_result" jsonb NOT NULL,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL,
    "input_tokens" integer,
    "output_tokens" integer,
    "total_tokens" integer,
    "processing_ms" integer,
    "estimated_cost_usd" numeric(12,8),
    "extraction_status" character varying(30) DEFAULT 'legacy'::character varying NOT NULL,
    "extraction_attempts" integer DEFAULT 0 NOT NULL,
    "extraction_error" text,
    "extraction_started_at" timestamp without time zone
);

CREATE TABLE public."post_extraction_logs" (
    "id" bigint DEFAULT nextval('post_extraction_logs_id_seq'::regclass) NOT NULL,
    "classification_id" bigint NOT NULL,
    "post_id" bigint NOT NULL,
    "model" character varying(100) NOT NULL,
    "status" character varying(30) NOT NULL,
    "product_count" integer,
    "input_tokens" integer,
    "output_tokens" integer,
    "total_tokens" integer,
    "processing_ms" integer,
    "estimated_cost_usd" numeric(12,8),
    "error_type" character varying(150),
    "created_at" timestamp without time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."post_images" (
    "id" bigint DEFAULT nextval('post_images_id_seq'::regclass) NOT NULL,
    "post_id" bigint NOT NULL,
    "image_index" integer NOT NULL,
    "s3_key" text NOT NULL,
    "content_type" character varying(100) NOT NULL,
    "size_bytes" bigint NOT NULL,
    "created_at" timestamp without time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."post_moderation" (
    "post_id" bigint NOT NULL,
    "is_hidden" boolean DEFAULT false NOT NULL,
    "reason" text,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."post_moderation_events" (
    "id" bigint DEFAULT nextval('post_moderation_events_id_seq'::regclass) NOT NULL,
    "post_id" bigint NOT NULL,
    "action" character varying(20) NOT NULL,
    "reason" text,
    "created_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."posts" (
    "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "source" character varying(30) NOT NULL,
    "source_post_id" character varying(255) NOT NULL,
    "url" text NOT NULL,
    "content" text,
    "published_at" timestamp with time zone,
    "collected_at" timestamp with time zone DEFAULT now() NOT NULL,
    "crawl_run_id" bigint,
    "facebook_group_id" bigint,
    "author_name" text,
    "reaction_count" integer,
    "comment_count" integer,
    "share_count" integer,
    "raw_data" jsonb,
    "author_id" character varying(255),
    "author_url" text,
    "facebook_group_external_id" character varying(255),
    "image_urls" jsonb,
    "listing" jsonb
);

CREATE TABLE public."scheduler_settings" (
    "id" integer NOT NULL,
    "enabled" boolean DEFAULT false NOT NULL,
    "interval_minutes" integer DEFAULT 60 NOT NULL,
    "timezone" character varying(100) DEFAULT 'Asia/Ho_Chi_Minh'::character varying NOT NULL,
    "updated_at" timestamp with time zone DEFAULT now() NOT NULL
);

CREATE TABLE public."stage1_claims" (
    "id" bigint DEFAULT nextval('stage1_claims_id_seq'::regclass) NOT NULL,
    "post_id" bigint NOT NULL,
    "prompt_version_id" bigint NOT NULL,
    "status" character varying(20) DEFAULT 'processing'::character varying NOT NULL,
    "claimed_at" timestamp without time zone DEFAULT now() NOT NULL,
    "completed_at" timestamp without time zone,
    "classification_id" bigint,
    "error_type" character varying(150)
);
ALTER SEQUENCE public."post_extraction_logs_id_seq" OWNED BY public."post_extraction_logs"."id";
ALTER SEQUENCE public."post_images_id_seq" OWNED BY public."post_images"."id";
ALTER SEQUENCE public."post_moderation_events_id_seq" OWNED BY public."post_moderation_events"."id";
ALTER SEQUENCE public."stage1_claims_id_seq" OWNED BY public."stage1_claims"."id";
ALTER TABLE public."ai_prompt_versions" ADD CONSTRAINT "ai_prompt_not_empty" CHECK ((length(TRIM(BOTH FROM system_prompt)) > 0));
ALTER TABLE public."ai_prompt_versions" ADD CONSTRAINT "ai_prompt_versions_pkey" PRIMARY KEY (id);
ALTER TABLE public."ai_prompt_versions" ADD CONSTRAINT "ai_prompt_versions_version_key" UNIQUE (version);
ALTER TABLE public."api_credentials" ADD CONSTRAINT "api_credentials_pkey" PRIMARY KEY (service);
ALTER TABLE public."api_credentials" ADD CONSTRAINT "valid_credential_service" CHECK (((service)::text = ANY ((ARRAY['openai'::character varying, 'apify'::character varying])::text[])));
ALTER TABLE public."author_skip_list" ADD CONSTRAINT "author_skip_list_facebook_author_id_key" UNIQUE (facebook_author_id);
ALTER TABLE public."author_skip_list" ADD CONSTRAINT "author_skip_list_pkey" PRIMARY KEY (id);
ALTER TABLE public."author_skip_list" ADD CONSTRAINT "author_skip_list_profile_url_key" UNIQUE (profile_url);
ALTER TABLE public."author_skip_list" ADD CONSTRAINT "author_skip_seller_only" CHECK (((skip_enabled = false) OR ((classification)::text = 'seller'::text)));
ALTER TABLE public."author_skip_list" ADD CONSTRAINT "valid_author_classification" CHECK (((classification)::text = ANY ((ARRAY['seller'::character varying, 'individual'::character varying, 'unknown'::character varying])::text[])));
ALTER TABLE public."author_skip_list" ADD CONSTRAINT "valid_author_identity" CHECK (((facebook_author_id IS NOT NULL) OR (profile_url IS NOT NULL)));
ALTER TABLE public."crawl_runs" ADD CONSTRAINT "crawl_runs_apify_run_id_key" UNIQUE (apify_run_id);
ALTER TABLE public."crawl_runs" ADD CONSTRAINT "crawl_runs_pkey" PRIMARY KEY (id);
ALTER TABLE public."crawler_settings" ADD CONSTRAINT "crawler_settings_id_check" CHECK ((id = 1));
ALTER TABLE public."crawler_settings" ADD CONSTRAINT "crawler_settings_max_posts_per_group_check" CHECK (((max_posts_per_group >= 1) AND (max_posts_per_group <= 100)));
ALTER TABLE public."crawler_settings" ADD CONSTRAINT "crawler_settings_max_total_charge_usd_check" CHECK (((max_total_charge_usd >= 0.01) AND (max_total_charge_usd <= 10.00)));
ALTER TABLE public."crawler_settings" ADD CONSTRAINT "crawler_settings_pkey" PRIMARY KEY (id);
ALTER TABLE public."facebook_groups" ADD CONSTRAINT "facebook_groups_pkey" PRIMARY KEY (id);
ALTER TABLE public."facebook_groups" ADD CONSTRAINT "facebook_groups_url_key" UNIQUE (url);
ALTER TABLE public."facebook_groups" ADD CONSTRAINT "valid_max_posts" CHECK (((max_posts IS NULL) OR (max_posts > 0)));
ALTER TABLE public."post_classifications" ADD CONSTRAINT "extraction_status_check" CHECK (((extraction_status)::text = ANY ((ARRAY['legacy'::character varying, 'not_required'::character varying, 'pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying])::text[])));
ALTER TABLE public."post_classifications" ADD CONSTRAINT "post_classifications_confidence_check" CHECK (((confidence >= (0)::double precision) AND (confidence <= (1)::double precision)));
ALTER TABLE public."post_classifications" ADD CONSTRAINT "post_classifications_pkey" PRIMARY KEY (id);
ALTER TABLE public."post_classifications" ADD CONSTRAINT "post_classifications_post_type_check" CHECK (((post_type)::text = ANY ((ARRAY['selling'::character varying, 'buying'::character varying, 'other'::character varying])::text[])));
ALTER TABLE public."post_classifications" ADD CONSTRAINT "post_classifications_seller_type_check" CHECK (((seller_type)::text = ANY ((ARRAY['individual'::character varying, 'seller'::character varying, 'unknown'::character varying])::text[])));
ALTER TABLE public."post_extraction_logs" ADD CONSTRAINT "post_extraction_logs_pkey" PRIMARY KEY (id);
ALTER TABLE public."post_extraction_logs" ADD CONSTRAINT "post_extraction_logs_status_check" CHECK (((status)::text = ANY ((ARRAY['completed'::character varying, 'failed'::character varying])::text[])));
ALTER TABLE public."post_images" ADD CONSTRAINT "post_images_pkey" PRIMARY KEY (id);
ALTER TABLE public."post_images" ADD CONSTRAINT "post_images_post_id_image_index_key" UNIQUE (post_id, image_index);
ALTER TABLE public."post_images" ADD CONSTRAINT "post_images_s3_key_key" UNIQUE (s3_key);
ALTER TABLE public."post_moderation" ADD CONSTRAINT "post_moderation_pkey" PRIMARY KEY (post_id);
ALTER TABLE public."post_moderation_events" ADD CONSTRAINT "post_moderation_events_action_check" CHECK (((action)::text = ANY ((ARRAY['hide'::character varying, 'restore'::character varying])::text[])));
ALTER TABLE public."post_moderation_events" ADD CONSTRAINT "post_moderation_events_pkey" PRIMARY KEY (id);
ALTER TABLE public."posts" ADD CONSTRAINT "posts_pkey" PRIMARY KEY (id);
ALTER TABLE public."posts" ADD CONSTRAINT "posts_crawl_run_id_fkey" FOREIGN KEY (crawl_run_id) REFERENCES public."crawl_runs"(id);
ALTER TABLE public."posts" ADD CONSTRAINT "posts_source_source_post_id_key" UNIQUE (source, source_post_id);
ALTER TABLE public."scheduler_settings" ADD CONSTRAINT "scheduler_settings_id_check" CHECK ((id = 1));
ALTER TABLE public."scheduler_settings" ADD CONSTRAINT "scheduler_settings_interval_minutes_check" CHECK (((interval_minutes >= 1) AND (interval_minutes <= 1440)));
ALTER TABLE public."scheduler_settings" ADD CONSTRAINT "scheduler_settings_pkey" PRIMARY KEY (id);
ALTER TABLE public."stage1_claims" ADD CONSTRAINT "stage1_claims_pkey" PRIMARY KEY (id);
ALTER TABLE public."stage1_claims" ADD CONSTRAINT "stage1_claims_post_id_prompt_version_id_key" UNIQUE (post_id, prompt_version_id);
ALTER TABLE public."stage1_claims" ADD CONSTRAINT "stage1_claims_status_check" CHECK (((status)::text = ANY ((ARRAY['processing'::character varying, 'completed'::character varying, 'failed'::character varying])::text[])));
ALTER TABLE public."post_classifications" ADD CONSTRAINT "post_classifications_post_id_fkey" FOREIGN KEY (post_id) REFERENCES posts(id) ON DELETE CASCADE;
ALTER TABLE public."post_classifications" ADD CONSTRAINT "post_classifications_prompt_version_id_fkey" FOREIGN KEY (prompt_version_id) REFERENCES ai_prompt_versions(id);
ALTER TABLE public."post_extraction_logs" ADD CONSTRAINT "post_extraction_logs_classification_id_fkey" FOREIGN KEY (classification_id) REFERENCES post_classifications(id);
ALTER TABLE public."post_extraction_logs" ADD CONSTRAINT "post_extraction_logs_post_id_fkey" FOREIGN KEY (post_id) REFERENCES posts(id);
ALTER TABLE public."post_images" ADD CONSTRAINT "post_images_post_id_fkey" FOREIGN KEY (post_id) REFERENCES posts(id);
ALTER TABLE public."post_moderation" ADD CONSTRAINT "post_moderation_post_id_fkey" FOREIGN KEY (post_id) REFERENCES posts(id);
ALTER TABLE public."post_moderation_events" ADD CONSTRAINT "post_moderation_events_post_id_fkey" FOREIGN KEY (post_id) REFERENCES posts(id);
ALTER TABLE public."posts" ADD CONSTRAINT "posts_facebook_group_id_fkey" FOREIGN KEY (facebook_group_id) REFERENCES facebook_groups(id);
ALTER TABLE public."stage1_claims" ADD CONSTRAINT "stage1_claims_classification_id_fkey" FOREIGN KEY (classification_id) REFERENCES post_classifications(id);
ALTER TABLE public."stage1_claims" ADD CONSTRAINT "stage1_claims_post_id_fkey" FOREIGN KEY (post_id) REFERENCES posts(id);
ALTER TABLE public."stage1_claims" ADD CONSTRAINT "stage1_claims_prompt_version_id_fkey" FOREIGN KEY (prompt_version_id) REFERENCES ai_prompt_versions(id);
CREATE UNIQUE INDEX ai_prompt_one_active ON public.ai_prompt_versions USING btree (is_active) WHERE (is_active = true);
CREATE INDEX idx_post_classifications_post ON public.post_classifications USING btree (post_id, created_at DESC);
CREATE INDEX idx_post_classifications_prompt ON public.post_classifications USING btree (prompt_version_id);
CREATE INDEX idx_extraction_logs_classification ON public.post_extraction_logs USING btree (classification_id);
CREATE INDEX idx_extraction_logs_created_at ON public.post_extraction_logs USING btree (created_at DESC);
CREATE INDEX idx_post_images_post ON public.post_images USING btree (post_id, image_index);
CREATE INDEX idx_stage1_claims_status ON public.stage1_claims USING btree (status, claimed_at);
COMMIT;
